# ── 내부 문서 목록 (검색/선택 화면) ─────────────────────────────────────────
def mock_documents():
    """내부 corpus 문서 목록을 반환합니다 (RAG 미연결 시 폴백)."""
    return [dict(d) for d in MOCK_DOCUMENTS]


_DOC_BY_ID = {d["document_id"]: d for d in MOCK_DOCUMENTS}


# ── 선택 문서 요약/요구사항 (워크스페이스) ──────────────────────────────────
def mock_analyze_selection(doc_ids, titles=None):
    """선택한 내부 문서(1건 이상)의 요약/요구사항/메타를 만들어 반환합니다.

    실제 데이터(사업명·발주기관·금액·요약)를 그대로 활용해, RAG 미연결 상태에서도
    화면이 그럴듯하게 채워집니다.
    """
    time.sleep(0.6)
    ids = list(doc_ids or [])
    picked = [_DOC_BY_ID[i] for i in ids if i in _DOC_BY_ID]
    if not picked:
        return {
            "meta": {"문서": "선택 없음"},
            "summary": "선택된 문서가 없습니다. 목록에서 문서를 먼저 선택해주세요.",
            "requirements": ["선택된 문서가 없습니다."],
        }

    head = picked[0]
    if len(picked) == 1:
        meta = {
            "사업명": head["title"],
            "발주기관": head["org"],
            "사업예산": head["amount"],
            "파일형식": head["ftype"].upper(),
            "청크 수": f'{head["chunk_count"]}개',
            "문서": head["title"],
        }
        summary = head["summary"] or (
            f'{head["org"]}가 발주한 "{head["title"]}" 사업입니다. '
            "세부 요약은 RAG 연결 후 실제 문서 기반으로 생성됩니다."
        )
        requirements = [
            f'[사업명] {head["title"]}',
            f'[발주기관] {head["org"]}',
            f'[사업예산] {head["amount"]}',
            "[참가자격] 관련 실적 보유 업체 (예시 · RAG 연결 시 실제 추출)",
            "[제출서류] 제안서, 사업수행계획서, 산출내역서 (예시)",
        ]
    else:
        names = ", ".join(p["title"] for p in picked)
        meta = {
            "선택 문서 수": f"{len(picked)}건",
            "대상": names[:60] + ("…" if len(names) > 60 else ""),
        }
        summary = (
            f"선택한 {len(picked)}개 문서를 비교 분석 대상으로 담았습니다. "
            "'핵심 요구사항' 탭에서 문서별 예산·발주기관을 비교할 수 있습니다. "
            "(RAG 연결 시 실제 문서 기반 비교로 대체됩니다.)"
        )
        requirements = [
            f'[{p["org"]}] {p["title"]} · {p["amount"]}' for p in picked
        ]

    return {"meta": meta, "summary": summary, "requirements": requirements}


def mock_compare(docs):
    """선택 문서들을 표 형태로 비교 (mock)."""
    rows = [
        {"문서": d["title"], "발주기관": d["org"], "사업예산": d["amount"],
         "파일형식": d["ftype"].upper()}
        for d in docs
    ]
    summary = f"선택한 {len(docs)}개 문서를 발주기관·예산 기준으로 비교했습니다."
    return {"summary": summary, "rows": rows}


