def mock_chat(question, titles=None):
    """질문에 대한 Mock 답변 + 출처. 실제로는 RAG 검색 결과를 반환."""
    scope = ""
    if titles:
        if len(titles) == 1:
            scope = f'"{titles[0]}" 문서 기준으로 답변드리면, '
        else:
            scope = f"선택한 {len(titles)}개 문서 기준으로 답변드리면, "

    if "마감" in question or "언제" in question or "기간" in question:
        ans = (scope + "제안서 제출 마감과 사업기간은 공고문 '일정' 항목에 명시됩니다. "
               "RAG 연결 시 문서 속 실제 날짜를 출처와 함께 안내합니다.")
        srcs = [("p.12", "2.3 제출 안내"), ("p.13", "2.4 일정표")]
    elif "예산" in question or "금액" in question:
        ans = (scope + "사업 예산은 공고문 '사업개요·대가' 항목에 기재되어 있습니다. "
               "선택 문서의 예산은 사업 개요 탭에서 바로 확인할 수 있습니다.")
        srcs = [("p.8", "1.4 사업 예산"), ("p.31", "5.2 대가 지급")]
    elif "자격" in question or "참가" in question:
        ans = (scope + "참가자격은 보통 관련 실적·면허·재무 요건으로 구성됩니다. "
               "'핵심 요구사항' 탭에서 추출된 자격 요건을 확인해보세요.")
        srcs = [("p.6", "1.2 참가 자격"), ("p.7", "1.3 제출 서류")]
    elif "보안" in question:
        ans = (scope + "보안 요구사항은 접근통제·암호화·인증 기준 중심으로 정리됩니다. "
               "RAG 연결 시 문서 내 실제 보안 조항을 출처와 함께 제시합니다.")
        srcs = [("p.42", "3.2 보안 요구사항"), ("p.44", "3.3 인증 기준")]
    else:
        ans = (scope + "질문하신 내용은 제안요청서 본문을 교차 확인해 답변합니다. "
               "예산·일정·자격·보안 등 구체적 항목으로 물어보시면 출처와 함께 안내해 드릴게요.")
        srcs = [("p.5", "1.1 사업 개요"), ("p.19", "3.1 요구사항 총괄")]
    return ans, srcs


def stream_words(text: str, delay: float = 0.02):
    """답변을 단어 단위로 흘려보내는 제너레이터 (타이핑 효과)."""
    acc = ""
    for word in text.split(" "):
        acc += word + " "
        yield acc
        time.sleep(delay)
